public class MainActivity extends Activity {
 private final ExecutorService workers=Executors.newFixedThreadPool(3);
 private final Handler main=new Handler(Looper.getMainLooper());
 private final Map<String,Provider.Item> store=new ConcurrentHashMap<>();
 private final Map<String,List<Provider.Item>> cache=new ConcurrentHashMap<>();
 private JSONArray accounts=new JSONArray();private Provider api;private JSONObject account;
 private WebView web;private ExoPlayer player;private PlayerView playerView;private TextView playerState;
 private Provider.Item playing;private String playingKind="live";private List<String> urls=new ArrayList<>();
 private int attempt=0,playGeneration=0;private volatile int accountGeneration=0;private boolean destroyed=false,inPlayer=false,showingFailure=false,foreground=false;
 private AppUpdates updates;private AppLanguage strings;private int previousOrientation=ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED;
 private final List<String> failures=new ArrayList<>();private Runnable watchdog;private String returnOrientation="";
 private android.content.SharedPreferences prefs(){return getSharedPreferences("options",0);}
 private String language(){return AppLanguage.language(prefs().getString("language","en"));}
 private String l(String value){return strings==null?value:strings.text(value,language());}
 @SuppressWarnings("deprecation") private void applyNativeLocale(){java.util.Locale locale=new java.util.Locale(language());java.util.Locale.setDefault(locale);Configuration config=new Configuration(getResources().getConfiguration());config.setLocale(locale);config.setLayoutDirection(locale);getResources().updateConfiguration(config,getResources().getDisplayMetrics());}
 private void rotatePlayback(){if(!inPlayer)return;boolean landscape=getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE;setRequestedOrientation(landscape?ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT:ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);}
 private int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 @Override public void onCreate(Bundle state){super.onCreate(state);applyNativeLocale();try(java.io.InputStream in=getAssets().open("i18n.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[4096];int count;while((count=in.read(buf))!=-1)out.write(buf,0,count);strings=new AppLanguage(out.toString("UTF-8"));}catch(Exception ignored){}getWindow().setStatusBarColor(Color.rgb(9,18,35));getWindow().setNavigationBarColor(Color.rgb(9,18,35));getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);try{accounts=new JSONArray(Vault.load(this));}catch(Exception e){Toast.makeText(this,l("تعذر قراءة الحسابات؛ أضف حسابك مرة أخرى"),1).show();}updates=new AppUpdates(this,()->foreground);createWeb();}
 @SuppressWarnings("deprecation") private void createWeb(){
  web=new WebView(this);web.setBackgroundColor(Color.rgb(9,18,35));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_ALWAYS_ALLOW);s.setSupportMultipleWindows(false);s.setTextZoom(100);s.setMediaPlaybackRequiresUserGesture(true);
  web.addJavascriptInterface(new Bridge(),"Sakan");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().equals("https://sakan.local/index.html");}@Override public boolean shouldOverrideUrlLoading(WebView v,String url){return !url.equals("https://sakan.local/index.html");}
   @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){UriParts uri=new UriParts(r.getUrl().toString());if(uri.local){try{String file=uri.path;if(file.isEmpty()||file.equals("/"))file="/index.html";if(file.contains(".."))return denied();String type=file.endsWith(".ttf")?"font/ttf":file.endsWith(".txt")?"text/plain":file.endsWith(".css")?"text/css":file.endsWith(".js")?"application/javascript":file.endsWith(".webp")?"image/webp":file.endsWith(".png")?"image/png":file.endsWith(".jpg")?"image/jpeg":"text/html";return new WebResourceResponse(type,"UTF-8",getAssets().open(file.substring(1)));}catch(Exception e){return denied();}}if(r.isForMainFrame())return denied();String scheme=r.getUrl().getScheme();if(!"http".equals(scheme)&&!"https".equals(scheme))return denied();return null;}
   private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
  });web.setWebChromeClient(new WebChromeClient());setContentView(web);web.loadUrl("https://sakan.local/index.html");
 }
 private static final class UriParts{final boolean local;final String path;UriParts(String s){java.net.URI u=java.net.URI.create(s);local="https".equals(u.getScheme())&&"sakan.local".equals(u.getHost());path=u.getPath();}}
 private JSONObject object(String value)throws Exception{return new JSONObject(value);}
 private void emit(String type,JSONObject value){main.post(()->{if(destroyed||web==null)return;try{JSONObject event=new JSONObject().put("type",type).put("data",value);web.evaluateJavascript("window.NativeEvents&&window.NativeEvents("+JSONObject.quote(event.toString())+")",null);}catch(Exception ignored){}});}
 private JSONObject json(String key,Object value){try{return new JSONObject().put(key,value);}catch(Exception e){return new JSONObject();}}
 private String safe(Exception e){if(ConnectionDiagnostics.ssl(e)||ConnectionDiagnostics.plaintextTls(e))return l(ConnectionDiagnostics.tls(e));String m=e.getMessage();if(e instanceof SocketTimeoutException)return l("انتهت مهلة الاتصال بالسيرفر. جرّب مرة أخرى.");if(e instanceof UnknownHostException)return l("تعذر العثور على السيرفر. راجع الرابط والإنترنت.");if(m==null)return l("تعذر إكمال الاتصال");return l(m).replaceAll("https?://\\S+",l("[عنوان السيرفر]")).substring(0,Math.min(l(m).replaceAll("https?://\\S+",l("[عنوان السيرفر]")).length(),240));}
 private void error(String message,String request){JSONObject j=json("message",message);try{j.put("request",request);}catch(Exception ignored){}emit("error",j);}
 private JSONObject find(String key){for(int i=0;i<accounts.length();i++){JSONObject p=accounts.optJSONObject(i);if(p!=null&&p.optString("key").equals(key))return p;}return null;}
 private void state(){try{JSONArray a=new JSONArray();for(int i=0;i<accounts.length();i++){JSONObject p=accounts.getJSONObject(i);a.put(new JSONObject().put("key",p.optString("key")).put("name",p.optString("name")).put("mode",p.optString("mode")));}emit("state",new JSONObject().put("accounts",a).put("selected",prefs().getString("selected","")).put("format",prefs().getString("format","auto")).put("agent",prefs().getString("agent","vlc")).put("updateRepository",updates.repository()).put("automaticUpdates",updates.automatic()).put("version","1.4").put("language",language()));}catch(Exception e){error(safe(e),"");}}
 private void persist()throws Exception{Vault.save(this,accounts.toString());}
 private String key(String kind,Provider.Item item){return kind+":"+(item.folder?"folder:":"item:")+item.id;}
 private boolean favorite(String kind,Provider.Item item){return getSharedPreferences("favorites",0).getBoolean(account.optString("key")+":"+key(kind,item),getSharedPreferences("favorites",0).getBoolean(account.optString("key")+":"+kind+":"+item.id,false));}
 private void sendItems(String event,String request,String kind,List<Provider.Item> list,LinkedHashMap<String,String> categories,int generation)throws Exception{
  if(generation!=accountGeneration)return;
  JSONObject start=new JSONObject().put("request",request).put("kind",kind).put("count",list.size());JSONArray c=new JSONArray();if(categories!=null)for(Map.Entry<String,String> e:categories.entrySet())c.put(new JSONObject().put("id",e.getKey()).put("name",e.getValue()));start.put("categories",c);emit(event+"Start",start);
  JSONArray batch=new JSONArray();for(int i=0;i<list.size();i++){if(generation!=accountGeneration)return;Provider.Item item=list.get(i);store.put(key(kind,item),item);batch.put(item.json(kind,favorite(kind,item)));if(batch.length()==100||i==list.size()-1){emit(event+"Chunk",new JSONObject().put("request",request).put("kind",kind).put("items",batch));batch=new JSONArray();}}
  emit(event+"End",json("request",request).put("kind",kind));
 }
 private void connect(JSONObject p,boolean save){accountGeneration++;int generation=accountGeneration;api=null;account=null;cache.clear();store.clear();workers.submit(()->{try{JSONObject copy=new JSONObject(p.toString());copy.put("agent",prefs().getString("agent","vlc").equals("vlc")?"VLC/3.0.21 LibVLC/3.0.21":"SakanIPTV/1.4");Provider client=new Provider(copy);client.login();main.post(()->{if(generation!=accountGeneration||destroyed)return;try{if(save){boolean updated=false;for(int i=0;i<accounts.length();i++)if(accounts.getJSONObject(i).optString("key").equals(p.optString("key"))){accounts.put(i,p);updated=true;break;}if(!updated)accounts.put(p);persist();}api=client;account=p;prefs().edit().putString("selected",p.optString("key")).apply();state();emit("connected",new JSONObject().put("key",p.optString("key")).put("name",p.optString("name")).put("mode",p.optString("mode")));}catch(Exception e){error(safe(e),"connect");}});}catch(Exception e){if(generation==accountGeneration){try{emit("error",new JSONObject().put("message",safe(e)).put("request","connect").put("suggestHttp",p.optString("url").startsWith("https://")&&ConnectionDiagnostics.plaintextTls(e)));}catch(Exception ignored){error(safe(e),"connect");}}}});}
 public final class Bridge {
  @JavascriptInterface public void call(String action,String payload){main.post(()->{try{dispatch(action,object(payload));}catch(Exception e){error(safe(e),"");}});}
 }
 private void dispatch(String action,JSONObject data)throws Exception{
  switch(action){
   case "ready":state();updates.check(false);break;
   case "checkUpdates":{String repo=data.optString("repository",updates.repository());updates.configure(repo,data.optBoolean("automatic",updates.automatic()));updates.check(true);break;}
   case "cancelPlay":playGeneration++;break;
   case "connect":{JSONObject p=find(data.optString("key"));if(p==null)throw new Exception(l("الحساب غير موجود"));connect(p,false);break;}
   case "edit":{JSONObject p=find(data.optString("key"));if(p!=null)emit("edit",p);break;}
   case "save":{JSONObject p=new JSONObject();String existing=data.optString("key");p.put("key",find(existing)==null?UUID.randomUUID().toString():existing);p.put("name",data.optString("name").trim().isEmpty()?l("اشتراكي"):data.optString("name").trim());p.put("url",Provider.normalize(data.optString("url")));String mode=data.optString("mode");if(!mode.equals("MAC")&&!mode.equals("XTREAM"))throw new Exception(l("نوع حساب غير صحيح"));p.put("mode",mode);for(String field:new String[]{"user","pass","mac","serial","device"})p.put(field,field.equals("pass")?data.optString(field):data.optString(field).trim());if(mode.equals("XTREAM")&&(p.optString("user").isEmpty()||p.optString("pass").isEmpty()))throw new Exception(l("أدخل اسم المستخدم وكلمة المرور"));connect(p,true);break;}
   case "delete":{String id=data.optString("key");for(int i=0;i<accounts.length();i++)if(accounts.getJSONObject(i).optString("key").equals(id)){accounts.remove(i);break;}persist();if(account!=null&&account.optString("key").equals(id)){api=null;account=null;accountGeneration++;cache.clear();store.clear();emit("disconnected",new JSONObject());}state();break;}
   case "catalog":{Provider client=api;if(client==null)throw new Exception(l("أضف حسابًا واتصل به أولًا"));String kind=data.optString("kind","live"),category=data.optString("category","*"),request=data.optString("request");if(!Arrays.asList("live","vod","series").contains(kind))throw new Exception(l("مكتبة غير صحيحة"));if(kind.equals("series")&&client.macMode){error(l("المسلسلات متاحة حاليًا لحسابات Xtream"),request);break;}int generation=accountGeneration;if(data.optBoolean("refresh"))cache.remove(kind+":"+category);workers.submit(()->{try{LinkedHashMap<String,String> categories=client.categories(kind);List<Provider.Item> list=cache.get(kind+":"+category);if(list==null){list=client.items(kind,category);if(generation==accountGeneration)cache.put(kind+":"+category,list);}sendItems("catalog",request,kind,list,categories,generation);}catch(Exception e){if(generation==accountGeneration)error(safe(e),request);}});break;}
   case "episodes":{Provider client=api;if(client==null)break;Provider.Item series=store.get("series:"+data.optString("uid"));String request=data.optString("request");int generation=accountGeneration;if(series==null||!series.folder)throw new Exception(l("اختر مسلسلًا من القائمة"));workers.submit(()->{try{sendItems("episodes",request,"series",client.episodes(series),null,generation);}catch(Exception e){if(generation==accountGeneration)error(safe(e),request);}});break;}
   case "play":{String kind=data.optString("kind");Provider.Item item=store.get(kind+":"+data.optString("uid"));if(item==null||item.folder)throw new Exception(l("اختر قناة أو حلقة من القائمة"));startPlayback(item,kind);break;}
   case "favorite":{String kind=data.optString("kind");Provider.Item item=store.get(kind+":"+data.optString("uid"));if(item==null||account==null)break;boolean value=!favorite(kind,item);getSharedPreferences("favorites",0).edit().putBoolean(account.optString("key")+":"+key(kind,item),value).putBoolean(account.optString("key")+":"+kind+":"+item.id,value).apply();emit("favorite",new JSONObject().put("kind",kind).put("uid",data.optString("uid")).put("favorite",value));break;}
   case "settings":{updates.configure(data.optString("updateRepository",updates.repository()),data.optBoolean("automaticUpdates",updates.automatic()));String f=data.optString("format","auto"),agent=data.optString("agent","vlc");if(!Arrays.asList("auto","hls","ts").contains(f))f="auto";if(!Arrays.asList("vlc","sakan").contains(agent))agent="vlc";prefs().edit().putString("format",f).putString("agent",agent).putString("language",AppLanguage.language(data.optString("language",language()))).apply();applyNativeLocale();if(api!=null)api.profile.put("agent",agent.equals("vlc")?"VLC/3.0.21 LibVLC/3.0.21":"SakanIPTV/1.4");state();emit("toast",json("message",l("تم حفظ إعدادات التشغيل")));break;}
  }
 }
 private void startPlayback(Provider.Item item,String kind){Provider client=api;if(client==null)return;int current=++playGeneration;int generation=accountGeneration;emit("loading",json("message",l("جارٍ تجهيز رابط البث…")));workers.submit(()->{try{List<String> links=client.streams(item,kind,prefs().getString("format","auto"));main.post(()->{if(current!=playGeneration||generation!=accountGeneration||destroyed)return;playing=item;playingKind=kind;urls=links;attempt=0;failures.clear();showingFailure=false;showPlayer();openAttempt();});}catch(Exception e){if(current==playGeneration)error(safe(e),"play");}});}
 private Button playerButton(String label,Runnable click){Button b=new Button(this);b.setText(label);b.setTextSize(13);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(30,43,67)));b.setOnClickListener(v->click.run());return b;}
 private void showPlayer(){if(!inPlayer)previousOrientation=getRequestedOrientation();release();inPlayer=true;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout page=new LinearLayout(this);page.setLayoutDirection(language().equals("ar")?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);page.setOrientation(1);page.setBackgroundColor(Color.BLACK);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),0,dp(8),0);row.addView(playerButton(l("رجوع"),this::stopPlayer),new LinearLayout.LayoutParams(dp(70),dp(44)));TextView title=new TextView(this);title.setText(playing.name);title.setTextColor(Color.WHITE);title.setTextSize(15);title.setSingleLine(true);title.setPadding(dp(12),0,dp(4),0);row.addView(title,new LinearLayout.LayoutParams(0,dp(44),1));Button rotate=playerButton("⟳",this::rotatePlayback);rotate.setMinWidth(0);rotate.setMinimumWidth(0);rotate.setPadding(0,0,0,0);rotate.setTextSize(24);rotate.setContentDescription(l("تدوير الشاشة"));if(android.os.Build.VERSION.SDK_INT>=26)rotate.setTooltipText(l("تدوير الشاشة"));row.addView(rotate,new LinearLayout.LayoutParams(dp(44),dp(44)));row.addView(playerButton(l("الصيغة"),this::chooseFormat),new LinearLayout.LayoutParams(dp(78),dp(44)));row.addView(playerButton(l("ملء الشاشة"),()->{if(playerView!=null)playerView.setResizeMode(playerView.getResizeMode()==AspectRatioFrameLayout.RESIZE_MODE_FIT?AspectRatioFrameLayout.RESIZE_MODE_ZOOM:AspectRatioFrameLayout.RESIZE_MODE_FIT);}),new LinearLayout.LayoutParams(dp(100),dp(44)));page.addView(row);playerState=new TextView(this);playerState.setTextColor(Color.rgb(134,159,190));playerState.setTextSize(11);playerState.setPadding(dp(14),dp(2),dp(14),dp(2));page.addView(playerState);playerView=new PlayerView(this);playerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);page.addView(playerView,new LinearLayout.LayoutParams(-1,0,1));setContentView(page);playerView.requestFocus();}
 private void openAttempt(){
  releaseEngine();if(!inPlayer||attempt>=urls.size())return;String url=urls.get(attempt);int current=playGeneration;int thisAttempt=attempt;
  playerState.setText(l("جارٍ الاتصال · ")+formatName(url)+l(" · محاولة ")+(attempt+1)+" / "+urls.size());
  DefaultExtractorsFactory extractors=new DefaultExtractorsFactory().setTsExtractorFlags(DefaultTsPayloadReaderFactory.FLAG_ALLOW_NON_IDR_KEYFRAMES|DefaultTsPayloadReaderFactory.FLAG_DETECT_ACCESS_UNITS);
  DefaultMediaSourceFactory sources=new DefaultMediaSourceFactory(()->new StreamDataSource(api),extractors);
  player=new ExoPlayer.Builder(this,new DefaultRenderersFactory(this).setEnableDecoderFallback(true)).setMediaSourceFactory(sources).build();playerView.setPlayer(player);player.setAudioAttributes(new AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);
  player.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int state){if(current!=playGeneration||thisAttempt!=attempt)return;if(state==Player.STATE_READY){clearWatchdog();playerState.setText(formatName(url)+"  •  "+(playingKind.equals("live")?l("بث مباشر"):l("تشغيل")));}}@Override public void onPlayerError(PlaybackException error){if(current!=playGeneration||thisAttempt!=attempt||!inPlayer)return;failed(diagnose(error));}});
  MediaItem.Builder media=new MediaItem.Builder().setUri(url);String mime=Provider.mime(url);if(mime!=null)media.setMimeType(mime);player.setMediaItem(media.build());player.prepare();if(foreground)player.play();
  watchdog=()->{if(inPlayer&&current==playGeneration&&thisAttempt==attempt&&player!=null&&player.getPlaybackState()!=Player.STATE_READY)failed(l("انتهت مهلة بدء البث · TIMEOUT"));};main.postDelayed(watchdog,22000);
 }
 private String formatName(String url){String mime=Provider.mime(url);return mime==null?(playingKind.equals("live")?l("MPEG-TS / مباشر"):l("فيديو")):mime.contains("mpegURL")?"HLS":"DASH";}
 private void failed(String reason){clearWatchdog();failures.add(formatName(urls.get(attempt))+": "+reason);if(attempt+1<urls.size()){attempt++;openAttempt();return;}releaseEngine();if(showingFailure||isFinishing())return;showingFailure=true;playerState.setText(l("تعذر بدء البث"));String message=reason+"\n\n"+android.text.TextUtils.join("\n",failures)+l("\n\nلم نتمكن من تشغيل الصيغ المتاحة. جرّب قناة أخرى؛ لو تكرر نفس الكود ابعت صورة الرسالة.");new AlertDialog.Builder(this).setTitle(l("تشخيص التشغيل")).setMessage(message).setPositiveButton(l("إعادة الاتصال"),(d,w)->{showingFailure=false;retry();}).setNeutralButton(l("الصيغة"),(d,w)->{showingFailure=false;chooseFormat();}).setNegativeButton(l("رجوع"),(d,w)->{showingFailure=false;stopPlayer();}).setOnCancelListener(d->{showingFailure=false;stopPlayer();}).show();}
 private String diagnose(PlaybackException e){int status=0;for(Throwable t=e;t!=null;t=t.getCause())if(t instanceof StreamConnection.Status){status=((StreamConnection.Status)t).code;break;}String code=e.getErrorCodeName();for(Throwable t=e;t!=null;t=t.getCause()){if(t instanceof java.net.UnknownHostException)return l("تعذر العثور على عنوان سيرفر البث · DNS · ")+code;if(t instanceof java.net.SocketTimeoutException)return l("السيرفر لم يرسل بيانات في المهلة المحددة · TIMEOUT · ")+code;if(t instanceof javax.net.ssl.SSLException)return l(ConnectionDiagnostics.tls(e))+" · TLS · "+code;}if(status!=0){String message=l(ConnectionDiagnostics.http(status));return message+" · HTTP "+status+" · "+code;}if(e.errorCode>=4000&&e.errorCode<6000)return l("ترميز الصوت أو الفيديو تعذر تشغيله على الجهاز · ")+code;if(e.errorCode==PlaybackException.ERROR_CODE_PARSING_CONTAINER_UNSUPPORTED||e.errorCode==PlaybackException.ERROR_CODE_PARSING_CONTAINER_MALFORMED)return l("رد السيرفر ليس صيغة فيديو مدعومة أو البث غير صالح · ")+code;if(e.errorCode==PlaybackException.ERROR_CODE_IO_NETWORK_CONNECTION_TIMEOUT)return l("مهلة الاتصال انتهت · ")+code;if(e.errorCode==PlaybackException.ERROR_CODE_IO_NETWORK_CONNECTION_FAILED)return l("تعذر الاتصال بعنوان البث · ")+code;return l("تعذر قراءة أو تشغيل البث · ")+code;}
 private void retry(){Provider.Item item=playing;String kind=playingKind;if(api!=null&&api.macMode){Provider client=api;int g=playGeneration;playerState.setText(l("تجديد جلسة MAC…"));workers.submit(()->{try{client.login();main.post(()->{if(g==playGeneration&&inPlayer)startPlayback(item,kind);});}catch(Exception e){main.post(()->{if(g==playGeneration&&inPlayer)new AlertDialog.Builder(this).setMessage(safe(e)).setPositiveButton(l("رجوع"),(d,w)->stopPlayer()).show();});}});}else startPlayback(item,kind);}
 private void chooseFormat(){new AlertDialog.Builder(this).setTitle(l("صيغة البث المفضلة")).setItems(new String[]{l("تلقائي · HLS ثم TS"),l("HLS أولًا"),l("MPEG-TS أولًا")},(d,w)->{prefs().edit().putString("format",new String[]{"auto","hls","ts"}[w]).apply();retry();}).show();}
 private void clearWatchdog(){if(watchdog!=null)main.removeCallbacks(watchdog);watchdog=null;}
 private void releaseEngine(){clearWatchdog();if(playerView!=null)playerView.setPlayer(null);if(player!=null){player.release();player=null;}}
 private void release(){releaseEngine();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 private void stopPlayer(){playGeneration++;release();inPlayer=false;showingFailure=false;setRequestedOrientation(previousOrientation);setContentView(web);web.requestFocus();emit("playbackClosed",new JSONObject());}
 @Override public void onBackPressed(){if(inPlayer){stopPlayer();return;}web.evaluateJavascript("window.onNativeBack&&window.onNativeBack()",value->{if("false".equals(value))new AlertDialog.Builder(this).setMessage(l("إغلاق Sakan IPTV؟")).setPositiveButton(l("إغلاق"),(d,w)->finish()).setNegativeButton(l("رجوع"),null).show();});}
 @Override public boolean onKeyDown(int code,KeyEvent event){if(inPlayer&&player!=null){if(code==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE){if(player.isPlaying())player.pause();else player.play();return true;}if((code==KeyEvent.KEYCODE_CHANNEL_UP||code==KeyEvent.KEYCODE_CHANNEL_DOWN)&&playingKind.equals("live")){List<Provider.Item> live=cache.get("live:*");if(live!=null&&!live.isEmpty()){int position=live.indexOf(playing);position=(position+(code==KeyEvent.KEYCODE_CHANNEL_UP?1:-1)+live.size())%live.size();startPlayback(live.get(position),"live");}return true;}}return super.onKeyDown(code,event);}
 @Override protected void onStart(){super.onStart();foreground=true;}
 @Override protected void onResume(){super.onResume();if(updates!=null)updates.resume();}
 @Override protected void onStop(){foreground=false;super.onStop();if(player!=null)player.pause();}
 @Override public void onConfigurationChanged(Configuration c){super.onConfigurationChanged(c);}
 @Override protected void onDestroy(){if(updates!=null)updates.close();destroyed=true;accountGeneration++;playGeneration++;release();workers.shutdownNow();if(web!=null){web.removeJavascriptInterface("Sakan");web.destroy();}super.onDestroy();}
}
